def extract_height(p):
    m=re.search(r'height.*?(\d{2,3})\.?(\d)?\s*(?:cm|centimeters)',p,re.I)
    if m:
        return float(m.group(1)+(m.group(2) or '.0'))
    m=re.search(r'height.*?(\d{2,3})\.?(\d)?\s*(?:cm|centimeters)',p,re.I)
    if m:
        return float(m.group(1))
    return None

def extract_pub(p):
    m=re.search(r'publisher\s+(\d+)',p,re.I)
    return int(m.group(1)) if m else None

for i,p in enumerate(parts[:200]):
    h=extract_height(p)
    pub=extract_pub(p)
    if h and pub:
        print(f'Part {i}: height={h}, pub={pub}')
        print(p[:800])
        break

